const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='pocket-atlas-china-v2',COLORS=['#2d6c53','#d46446','#d69b29','#416eb3','#825ab4','#ca6894'],ICONS=['📍','🍜','☕','🏨','🏛','🛍','🌿','📷','⭐','🚉'];
const initial={maps:[{id:'shanghai',name:'Shanghai · a little detour'},{id:'hangzhou',name:'Hangzhou weekend'}],places:[{id:'bund',map:'shanghai',name:'The Bund · 外滩',lat:31.2401,lng:121.4905,color:COLORS[1],icon:'📷',note:'Example pin — river views and an evening walk. Confirm the exact entrance in AMap before travelling.'},{id:'garden',map:'shanghai',name:'Yu Garden · 豫园',lat:31.2272,lng:121.4871,color:COLORS[0],icon:'🌿',note:'Example pin — leave time to explore the surrounding streets.'},{id:'temple',map:'shanghai',name:'Jing’an Temple · 静安寺',lat:31.2236,lng:121.4453,color:COLORS[3],icon:'🏛',note:'Example pin — a stop on the west side of the city.'},{id:'lake',map:'hangzhou',name:'West Lake · 西湖',lat:30.2431,lng:120.15,color:COLORS[4],icon:'🌿',note:'Example pin — choose your own spot along the lake.'}],active:'shanghai'};
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state?.maps?.length||!Array.isArray(state.places))state=null}catch{}state=state||structuredClone(initial);let active=state.maps.some(m=>m.id===state.active)?state.active:state.maps[0].id,selected=null,adding=false,draft=null;
function persist(){state.active=active;try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Storage is full or unavailable. Export a backup before leaving.');return false}}
let toastTimer;function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3500)}
const map=L.map('map',{zoomControl:false}).setView([31.232,121.472],12),markers=L.layerGroup().addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);
const myPlaces=()=>state.places.filter(p=>p.map===active),currentMap=()=>state.maps.find(m=>m.id===active),visible=()=>myPlaces().filter(p=>(p.name+' '+p.note).toLowerCase().includes($('search').value.toLowerCase()));
function icon(p){return L.divIcon({className:'',html:`<div class="pin" style="background:${p.color}"><span>${esc(p.icon)}</span></div>`,iconSize:[39,39],iconAnchor:[20,39]})}
function render(){ $('mapselect').innerHTML=state.maps.map(m=>`<option value="${esc(m.id)}" ${m.id===active?'selected':''}>${esc(m.name)}</option>`).join('');$('mapname').textContent=currentMap().name;$('count').textContent=`${myPlaces().length} SAVED ${myPlaces().length===1?'PLACE':'PLACES'}`;const list=visible();$('list').innerHTML=list.length?list.map(p=>`<button class="place ${selected===p.id?'selected':''}" data-place="${esc(p.id)}"><span class="emoji" style="background:${p.color}20;border-left:4px solid ${p.color}">${esc(p.icon)}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.note.slice(0,64)||'Add a note for this place')}</small></span><span class="arrow">↗</span></button>`).join(''):`<p class="empty">${myPlaces().length?'No matching saved places.':'Your map is ready. Tap “Add place” to drop your first pin.'}</p>`;markers.clearLayers();myPlaces().forEach(p=>L.marker([p.lat,p.lng],{icon:icon(p),title:p.name}).addTo(markers).on('click',()=>show(p.id)));$('cancelpick').hidden=!adding;$('add').textContent=adding?'Tap the map to drop a pin':'＋ Add place';}
function fit(){closeDetail();const ps=myPlaces();if(ps.length)map.fitBounds(ps.map(p=>[p.lat,p.lng]),{padding:[65,65],maxZoom:14});else map.setView([35.5,104.5],4)}
function closeDetail(){selected=null;$('detail').hidden=true;render()}
function chooseStyle(p){return `<fieldset><legend>Pin color</legend><div class="swatches">${COLORS.map(c=>`<label class="swatch" style="--color:${c}"><input type="radio" name="color" value="${c}" ${p.color===c?'checked':''} aria-label="${({'#2d6c53':'Green','#d46446':'Coral','#d69b29':'Gold','#416eb3':'Blue','#825ab4':'Purple','#ca6894':'Pink'})[c]}"><span></span></label>`).join('')}</div></fieldset><label>Pin icon<select name="icon">${ICONS.map(i=>`<option value="${i}" ${p.icon===i?'selected':''}>${i} ${({'📍':'Place','🍜':'Food','☕':'Coffee','🏨':'Stay','🏛':'Culture','🛍':'Shopping','🌿':'Nature','📷':'Photo','⭐':'Favorite','🚉':'Transport'})[i]}</option>`).join('')}</select></label>`}
function show(id){if(adding)return;const p=state.places.find(p=>p.id===id);if(!p)return;selected=id;render();map.flyTo([p.lat,p.lng],Math.max(map.getZoom(),14),{duration:.45});$('detail').hidden=false;$('detail').innerHTML=`<button class="close" id="closedetail" aria-label="Close place">×</button><span class="tag">${esc(currentMap().name)}</span><h2>${esc(p.icon)} ${esc(p.name)}</h2><a class="navigate" id="navigate" target="_blank" rel="noopener">↗ Navigate in AMap · 高德地图</a><form id="editform"><label>Place name<input name="name" value="${esc(p.name)}" required maxlength="80"></label><label>Notes<textarea name="note" maxlength="2000" placeholder="Entrance, opening hours, what to order…">${esc(p.note)}</textarea></label>${chooseStyle(p)}<div class="actions"><button class="primary">Save changes</button><button type="button" id="remove">Remove pin</button></div></form><p class="hint">Navigation opens AMap with this pin’s coordinates. App launch depends on your browser and installed apps.</p>`;$('navigate').href=navigationURL(p);$('closedetail').onclick=closeDetail;$('editform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name){toast('Enter a place name');return}Object.assign(p,{name,note:f.get('note'),color:f.get('color'),icon:f.get('icon')});persist();show(id);toast('Place updated')};$('remove').onclick=()=>{state.places=state.places.filter(x=>x.id!==id);persist();closeDetail();toast('Pin removed. Your exported backups are unchanged.')};}
// OSM uses WGS84; AMap uses GCJ-02 in mainland China. Convert only at the handoff.
function wgsToGcj(lat,lng){if(lng<72.004||lng>137.8347||lat<.8293||lat>55.8271)return[lat,lng];const pi=Math.PI,x=lng-105,y=lat-35;let a=-100+2*x+3*y+.2*y*y+.1*x*y+.2*Math.sqrt(Math.abs(x)),b=300+x+2*y+.1*x*x+.1*x*y+.1*Math.sqrt(Math.abs(x));a+=(20*Math.sin(6*x*pi)+20*Math.sin(2*x*pi))*2/3;a+=(20*Math.sin(y*pi)+40*Math.sin(y/3*pi))*2/3;a+=(160*Math.sin(y/12*pi)+320*Math.sin(y*pi/30))*2/3;b+=(20*Math.sin(6*x*pi)+20*Math.sin(2*x*pi))*2/3;b+=(20*Math.sin(x*pi)+40*Math.sin(x/3*pi))*2/3;b+=(150*Math.sin(x/12*pi)+300*Math.sin(x/30*pi))*2/3;const r=lat*pi/180,s=Math.sin(r),magic=1-.006693421622965943*s*s,root=Math.sqrt(magic);return[lat+a*180/((6378245*(1-.006693421622965943))/(magic*root)*pi),lng+b*180/(6378245/root*Math.cos(r)*pi)]}
function gcjToWgs(lat,lng){let a=lat,b=lng;for(let i=0;i<5;i++){const p=wgsToGcj(a,b);a-=p[0]-lat;b-=p[1]-lng}return[a,b]}
function navigationURL(p){const [lat,lng]=wgsToGcj(p.lat,p.lng);return 'https://uri.amap.com/navigation?'+new URLSearchParams({to:`${lng.toFixed(6)},${lat.toFixed(6)},${p.name}`,mode:'walk',src:'PocketAtlas',coordinate:'gaode',callnative:'1'})}
function openAdd(lat,lng){draft={lat,lng};adding=false;render();const f=$('addform');f.reset();f.elements.lat.value=lat.toFixed(6);f.elements.lng.value=lng.toFixed(6);$('addstyle').innerHTML=chooseStyle({color:COLORS[0],icon:'📍'});$('adddialog').showModal()}
map.on('click',e=>{if(adding)openAdd(e.latlng.lat,e.latlng.lng)});$('add').onclick=()=>{closeDetail();adding=true;render();toast('Tap the map to drop a pin')};$('cancelpick').onclick=()=>{adding=false;render()};$('coordinates').onclick=()=>{const c=map.getCenter();openAdd(c.lat,c.lng)};$('cancel').onclick=()=>$('adddialog').close();$('addform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name){toast('Enter a place name');return}let lat=Number(f.get('lat')),lng=Number(f.get('lng'));if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180){toast('Enter valid latitude and longitude');return}if(f.get('system')==='gcj') [lat,lng]=gcjToWgs(lat,lng);const p={id:crypto.randomUUID(),map:active,name,lat,lng,color:f.get('color'),icon:f.get('icon'),note:f.get('note')};state.places.push(p);persist();$('adddialog').close();$('search').value='';render();show(p.id);toast('Place saved to this map')};
$('list').onclick=e=>{const b=e.target.closest('[data-place]');if(b)show(b.dataset.place)};$('search').oninput=render;$('mapselect').onchange=e=>{active=e.target.value;adding=false;$('search').value='';persist();fit()};$('fit').onclick=fit;$('newmap').onclick=()=>{$('mapform').reset();$('mapdialog').showModal()};$('mapcancel').onclick=()=>$('mapdialog').close();$('mapform').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;const m={id:crypto.randomUUID(),name};state.maps.push(m);active=m.id;persist();$('mapdialog').close();$('search').value='';fit();toast('Custom map created')};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...state,active},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pocket-atlas-maps.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Maps exported')};$('import').onclick=()=>$('importfile').click();$('importfile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(!Array.isArray(incoming.maps)||!Array.isArray(incoming.places)||!incoming.maps.length||incoming.maps.length>100||incoming.places.length>10000)throw Error();const mapIds=new Map();for(const m of incoming.maps){if(typeof m.id!=='string'||typeof m.name!=='string'||!m.name.trim())throw Error();if(mapIds.has(m.id))throw Error();mapIds.set(m.id,crypto.randomUUID())}const newPlaces=incoming.places.map(p=>{if(!mapIds.has(p.map)||typeof p.name!=='string'||typeof p.note!=='string'||!Number.isFinite(p.lat)||!Number.isFinite(p.lng)||Math.abs(p.lat)>90||Math.abs(p.lng)>180||!COLORS.includes(p.color)||!ICONS.includes(p.icon))throw Error();return{id:crypto.randomUUID(),map:mapIds.get(p.map),name:p.name.slice(0,80),note:p.note.slice(0,2000),lat:p.lat,lng:p.lng,color:p.color,icon:p.icon}});state.maps.push(...incoming.maps.map(m=>({id:mapIds.get(m.id),name:m.name.slice(0,80)})));state.places.push(...newPlaces);active=mapIds.get(incoming.maps[0].id);persist();fit();toast('Backup imported as new maps')}catch{toast('That file is not a valid Pocket Atlas backup')}e.target.value=''};render();fit();
